/**
 * M5 tail equivalence — the offset read against the naive oracle of
 * m5-tail-semantics.spec.ts (which is proven equal to the pre-patch
 * production binary search in that file's 300-round test).
 *
 * "Byte-for-byte" means the whole result shape: `text` AND `truncated`,
 * compared as strings — including the lone-low-surrogate quirk, which a naive
 * byte-offset tail would turn into U+FFFD.
 *
 * Content is generated by CODE POINT (Array.from), because a JS string with a
 * lone surrogate is not what a file on disk can hold: UTF-8 decoding never
 * produces one, so such content falls under the declared non-UTF-8 deviation
 * in `readTailFile` rather than under equivalence.
 */
import { mkdtemp, rm, writeFile } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { afterEach, beforeEach, describe, expect, it } from 'vitest'
import { CortexStore } from '../src/host/store.ts'

let root = ''
let store: CortexStore
let jobId = ''

beforeEach(async () => {
  root = await mkdtemp(join(tmpdir(), 'm5-equiv-'))
  store = new CortexStore({ root })
  await store.init()
  const job = await store.createJob({ runner: 'probe', argv: ['/bin/true'], task: 'tail equivalence' })
  if (!job.ok || job.data === undefined) throw new Error('job create failed')
  jobId = job.data.id
})

afterEach(async () => {
  await rm(root, { recursive: true, force: true }).catch(() => {})
})

/** The documented rule, as a linear scan (same oracle as the semantics spec). */
function oracleTail(text: string, bytes: number): string {
  if (bytes <= 0) return ''
  if (Buffer.byteLength(text, 'utf8') <= bytes) return text
  for (let index = 0; index < text.length; index += 1) {
    if (Buffer.byteLength(text.slice(index), 'utf8') < bytes) return text.slice(index)
  }
  return ''
}

function oracle(content: string, bytes: number): { text: string; truncated: boolean } {
  const text = oracleTail(content, bytes)
  return { text, truncated: Buffer.byteLength(content, 'utf8') > Buffer.byteLength(text, 'utf8') }
}

async function svcTail(content: string, tailBytes: number): Promise<{ text: string; truncated: boolean }> {
  const { DelegateService } = await import('../src/host/modules/delegate/service.ts')
  const { resolveConfig } = await import('../src/host/config.ts')
  await writeFile(store.jobPaths(jobId).stdout, content, 'utf8')
  const deps = {
    ctx: {} as never,
    cfg: () => resolveConfig({}),
    store,
    log: () => {},
    warn: () => {},
    runtime: () => ({ modules: [], errors: [] }),
  } as never
  return await new DelegateService(deps as never).tail('stdout', jobId, tailBytes)
}

describe('M5 tail offset-read: byte-for-byte equivalence', () => {
  it('boundary sweep: size {bytes-1, bytes, bytes+1, +4, +5, +8} x alphabets', async () => {
    const alphabets: Array<{ name: string; text: string }> = [
      { name: 'ascii', text: 'abcdefgh\n' },
      { name: 'bmp-multibyte', text: '中文测试 é\n' },
      { name: 'astral', text: '😀🎉🚀\n' },
      { name: 'mixed', text: 'a中😀b é中😀\n' },
    ]
    for (const bytes of [1, 2, 3, 4, 5, 10, 256]) {
      for (const alphabet of alphabets) {
        for (const delta of [-1, 0, 1, 4, 5, 8]) {
          const size = bytes + delta
          if (size < 1) continue
          let content = ''
          while (Buffer.byteLength(content, 'utf8') < size) content += alphabet.text
          // Trim to the target size without splitting a codepoint, then pad.
          const trimmed = Buffer.from(content, 'utf8').subarray(0, size).toString('utf8')
          content = trimmed
          while (Buffer.byteLength(content, 'utf8') < size) content += 'x'
          if (Buffer.byteLength(content, 'utf8') > size) content = Buffer.from(content, 'utf8').subarray(0, size).toString('utf8')
          const label = `${alphabet.name} size=${Buffer.byteLength(content, 'utf8')} bytes=${bytes}`
          expect(await svcTail(content, bytes), label).toEqual(oracle(content, bytes))
        }
      }
    }
  }, 60_000)

  it('astral START exactly at size-bytes: the mid-pair quirk survives the offset read', async () => {
    for (const bytes of [12, 16, 256, 4096]) {
      for (let astralIndex = 0; astralIndex < 3; astralIndex += 1) {
        // head = bytes; three astrals at [bytes, bytes+12); tail long enough
        // that size-bytes lands exactly on astral #astralIndex.
        //   size - bytes = bytes + 4*astralIndex  (the astral's start)
        //   size = bytes + 12 + tail  ->  tail = bytes + 4*astralIndex - 12
        const tailLength = bytes + 4 * astralIndex - 12
        if (tailLength < 0) continue
        const content = `${'x'.repeat(bytes)}${'😀'.repeat(3)}${'y'.repeat(tailLength)}`
        const size = Buffer.byteLength(content, 'utf8')
        expect(size - bytes, 'cut offset must land on an astral start').toBe(bytes + 4 * astralIndex)
        const label = `astral #${astralIndex} bytes=${bytes}`
        expect(await svcTail(content, bytes), label).toEqual(oracle(content, bytes))
        // And the oracle really produced the quirk here (lone low surrogate),
        // otherwise this case would pass vacuously.
        const expected = oracle(content, bytes)
        expect(expected.text.charCodeAt(0), `${label} must exercise the mid-pair quirk`).toBeGreaterThanOrEqual(0xdc00)
        expect(expected.text.charCodeAt(0)).toBeLessThanOrEqual(0xdfff)
      }
    }
  }, 60_000)

  it('randomized content x random budget: 400 rounds, code-point generation', async () => {
    let seed = 0xc0ffee
    const rand = (): number => {
      seed = (seed * 1103515245 + 12345) & 0x7fffffff
      return seed / 0x7fffffff
    }
    const alphabets = ['abcdefgh', '中文测试字符', 'éèêü', '😀🎉🚀中', 'mixed 中 a 😀 x\n'].map(part => Array.from(part))
    for (let round = 0; round < 400; round += 1) {
      const alphabet = alphabets[Math.floor(rand() * alphabets.length)] ?? ['x']
      const length = Math.floor(rand() * 120)
      const codePoints: string[] = []
      for (let i = 0; i < length; i += 1) codePoints.push(alphabet[Math.floor(rand() * alphabet.length)] ?? 'x')
      const content = codePoints.join('')
      const bytes = 1 + Math.floor(rand() * 64)
      const expected = oracle(content, bytes)
      expect(await svcTail(content, bytes), `round ${round} bytes=${bytes} ${JSON.stringify(content.slice(0, 20))}`).toEqual(expected)
    }
  }, 60_000)
})

describe('M5 BENCH: legacy full read vs offset read, same run, same file', () => {
  it('times both implementations on pre-written files (no write in the loop)', async () => {
    const { readTailFile, tailByBytes } = await import('../src/host/modules/delegate/runner.ts')
    const { readTextSafe } = await import('../src/lib/fsx.ts')
    const file = store.jobPaths(jobId).stdout

    /** The pre-patch tail body, verbatim: full read + tailByBytes twice. */
    const legacy = async (path: string, tailBytes: number): Promise<{ text: string; truncated: boolean }> => {
      const raw = (await readTextSafe(path)) ?? ''
      return { text: tailByBytes(raw, tailBytes), truncated: Buffer.byteLength(raw, 'utf8') > Buffer.byteLength(tailByBytes(raw, tailBytes), 'utf8') }
    }

    const sizes = [
      { name: 'small 64 B', size: 64 },
      { name: 'exact 8192 B', size: 8192 },
      { name: 'large 1 MiB', size: 1024 * 1024 },
    ]
    for (const { name, size } of sizes) {
      await writeFile(file, 'x'.repeat(size), 'utf8')
      const rounds = 50
      // Both implementations see the identical pre-written file.
      let started = performance.now()
      for (let round = 0; round < rounds; round += 1) await legacy(file, 8192)
      const legacyMs = (performance.now() - started) / rounds
      started = performance.now()
      for (let round = 0; round < rounds; round += 1) await readTailFile(file, 8192)
      const offsetMs = (performance.now() - started) / rounds
      const speedup = legacyMs / offsetMs
      console.log(`BENCH tail ${name}: legacy ${legacyMs.toFixed(3)} ms -> offset ${offsetMs.toFixed(3)} ms (${speedup.toFixed(1)}x)`)
      // Equivalence first, performance second: same answer on this file.
      expect(await readTailFile(file, 8192)).toEqual(await legacy(file, 8192))
      if (name.startsWith('large')) expect(offsetMs, 'the 1 MiB case must win clearly').toBeLessThan(legacyMs)
    }
  }, 60_000)
})
